 V('opening remark=comentário de abertura|slide deck=conjunto de slides|speaker notes=anotações do apresentador|call to action=chamada para ação|key takeaway=conclusão principal|transition phrase=frase de transição|audience rapport=sintonia com o público|supplier proposal=proposta de fornecedor|selection committee=comitê de seleção|cost breakdown=detalhamento de custos|stage fright=medo de palco|eye contact=contato visual|pacing=ritmo da fala|closing summary=resumo de encerramento|question time=momento de perguntas|handout=material distribuído|rehearsal run=ensaio|time slot=horário reservado|visual aid=recurso visual|talking point=ponto de fala|pitch deck=apresentação para investidores|executive summary=resumo executivo|panel discussion=debate em painel|projector glitch=falha do projetor|laser pointer=ponteiro a laser|backup copy=cópia de segurança|opening hook=gancho de abertura|audience poll=enquete com o público'),
